content.query:
let cost = customMetrics | where name == "agentos.llm.cost.usd" | summarize CostUsd = round(sum(valueSum), 4), Calls = sum(valueCount) by Agent = tostring(customDimensions["gen_ai.agent.name"]), Model = tostring(customDimensions["gen_ai.request.model"]);
let tokens = customMetrics | where name == "agentos.llm.tokens" | extend Class = tostring(customDimensions["agentos.token.class"]) | summarize FreshInput = sumif(valueSum, Class == "fresh_input"), CacheRead = sumif(valueSum, Class == "cache_read"), CacheWrite = sumif(valueSum, Class == "cache_write"), Output = sumif(valueSum, Class == "output") by Agent = tostring(customDimensions["gen_ai.agent.name"]), Model = tostring(customDimensions["gen_ai.request.model"]);
cost | join kind=fullouter tokens on Agent, Model
| project Agent = coalesce(Agent, Agent1), Model = coalesce(Model, Model1), CostUsd, Calls, FreshInput, CacheRead, CacheWrite, Output
| order by CostUsd desc
